const pendingWrites=new Set();async function api(url,data){if(data===undefined)return OwaysAPI.request(url);if(pendingWrites.has(url))throw Error('جارٍ حفظ البيانات، يرجى الانتظار.');pendingWrites.add(url);const buttons=[...document.querySelectorAll('form button')].filter(b=>!b.disabled);buttons.forEach(b=>{b.disabled=true;b.setAttribute('aria-busy','true')});try{return await OwaysAPI.request(url,data)}finally{pendingWrites.delete(url);buttons.forEach(b=>{b.disabled=false;b.removeAttribute('aria-busy')});if(imageBusy)$('#next-step').disabled=true}}const E=OwaysAPI.escape,$=s=>document.querySelector(s);function status(m){$('#status').textContent=m;if(!m)return;if(/^تم /.test(m)){showSuccess(m);return}$('#notice-text').textContent=m;$('#admin-notice').hidden=false;$('#admin-notice').classList.remove('error')}async function run(fn){try{await fn()}catch(e){status(e.message);$('#admin-notice').classList.add('error')}}async function refresh(){const [c,s,o]=await Promise.all([api('/api/admin/categories'),api('/api/admin/services'),api('/api/admin/orders')]);$('#admin-stats').innerHTML=[['إجمالي الطلبات',o.orders.length],['بانتظار المراجعة',o.orders.filter(x=>x.fulfillment_status==='review').length],['الخدمات',s.services.length],['التصنيفات',c.categories.length]].map(([label,value])=>`<article><small>${E(label)}</small><strong>${value}</strong></article>`).join('');$('#category-select').innerHTML=c.categories.map(c=>`<option value="${E(c.id)}">${E(c.name)}</option>`).join('');$('#categories').innerHTML=c.categories.map(c=>`<p>${E(c.name)}</p>`).join('');adminServices=s.services;const filter=$('#service-category-filter'),selected=filter.value;filter.innerHTML='<option value="">جميع التصنيفات</option>'+c.categories.map(category=>`<option value="${E(category.id)}">${E(category.name)}</option>`).join('');filter.value=selected;renderAdminServices();adminOrders=o.orders;renderAdminOrders()}


let adminOrders=[];
const adminStates={review:'قيد المراجعة',awaiting_customer:'بانتظار العميل',ready:'جاهز للتنفيذ',processing:'قيد التنفيذ',completed:'مكتمل',cancelled:'ملغي',draft:'مسودة',awaiting_payment:'بانتظار الدفع',not_required_yet:'بانتظار عرض السعر',verification:'قيد التحقق',paid:'مدفوع',active:'نشطة',inactive:'غير نشطة',archived:'مؤرشفة'};
function adminState(value){return adminStates[value]||'غير محدد'}
function renderAdminOrders(){
 const query=$('#order-search').value.trim().toLocaleLowerCase(),filter=$('#order-filter').value;
 const orders=adminOrders.filter(o=>(!filter||o.fulfillment_status===filter)&&(!query||[o.public_reference,o.full_name,o.phone].some(v=>String(v||'').toLocaleLowerCase().includes(query))));
 $('#orders-summary').textContent='عرض '+orders.length+' من '+adminOrders.length+' طلب ضمن القائمة المحمّلة';
 $('#orders').innerHTML=orders.length?orders.map(o=>`<article class="portal-row admin-order-row"><div class="order-customer"><bdi class="order-reference" dir="ltr">${E(o.public_reference)}</bdi><strong>${E(o.full_name)}</strong><bdi class="order-phone" dir="ltr">${E(o.phone)}</bdi></div><div class="order-badges"><span class="admin-badge" data-state="${E(o.fulfillment_status)}">${E(adminState(o.fulfillment_status))}</span><span class="admin-badge payment-badge" data-state="${E(o.payment_status)}">${E(adminState(o.payment_status))}</span></div><button class="button outline" data-order="${E(o.id)}">مراجعة الطلب ←</button></article>`).join(''):'<div class="admin-empty"><h3>'+ (adminOrders.length?'لا توجد نتائج مطابقة':'لا توجد طلبات بعد')+'</h3><p>'+ (adminOrders.length?'غيّر كلمة البحث أو حالة التنفيذ.':'ستظهر طلبات العملاء هنا عند إضافتها.')+'</p></div>';
}
$('#order-search').addEventListener('input',renderAdminOrders);$('#order-filter').addEventListener('change',renderAdminOrders);
$('#refresh-admin').onclick=()=>run(async()=>{const button=$('#refresh-admin');button.disabled=true;button.textContent='جارٍ التحديث…';try{await refresh()}finally{button.disabled=false;button.textContent='تحديث الطلبات'}});

$('#category-form').onsubmit=e=>{e.preventDefault();run(async()=>{await api('/api/admin/categories',Object.fromEntries(new FormData(e.target)));e.target.reset();status('تم حفظ التصنيف.');await refreshAfterSave()})};$('#add-requirement').onclick=()=>{const row=document.createElement('div');row.className='requirement-row';row.innerHTML='<input data-key type="hidden"><label>اسم الحقل<input data-label required></label><label>النوع<select data-type><option value="text">نص</option><option value="email">بريد إلكتروني</option><option value="phone">هاتف</option><option value="url">رابط</option><option value="number">رقم</option><option value="textarea">نص طويل</option><option value="select">اختيار</option></select></label><label>شرح الإدخال<input data-help></label><label>خيارات الاختيار، خيار في كل سطر<textarea data-options></textarea></label><label><input type="checkbox" data-required checked>مطلوب</label><button type="button" class="button outline" data-remove-field>حذف الحقل</button>';row.querySelector('[data-key]').value='field_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,7);$('#requirements').append(row);const type=row.querySelector('[data-type]'),options=row.querySelector('[data-options]');function updateOptions(){options.closest('label').hidden=type.value!=='select';options.required=type.value==='select'}type.onchange=updateOptions;updateOptions();row.querySelector('[data-label]').focus()};$('#service-form').onsubmit=e=>{e.preventDefault();if(!validateService())return;run(async()=>{if(imageBusy){status('انتظر حتى ينتهي تجهيز الصورة.');return}const b=Object.fromEntries(new FormData(e.target));b.image=serviceImage;b.features=b.features.split('\n').map(x=>x.trim()).filter(Boolean);b.instructions={before_order:b.before_order,during_activation:b.during_activation,after_completion:b.after_completion};b.requirements=[...document.querySelectorAll('.requirement-row')].map(r=>({field_key:r.querySelector('[data-key]').value,label:r.querySelector('[data-label]').value,input_type:r.querySelector('[data-type]').value,required:r.querySelector('[data-required]').checked,help_text:r.querySelector('[data-help]').value,options:r.querySelector('[data-options]').value.split('\n').map(x=>x.trim()).filter(Boolean)}));await api('/api/admin/services',b);e.target.reset();clearServiceImage();$('#requirements').innerHTML='';updateDuration();serviceForm.elements.pricing_mode.dispatchEvent(new Event('change'));setServiceStep(0);$('#service-editor').hidden=true;status('تم حفظ الخدمة وباقتها.');await refreshAfterSave()})};document.addEventListener('click',e=>{const tab=e.target.closest('[data-tab]');if(tab){const view=tab.dataset.view||tab.dataset.tab;const headings={orders:['إدارة الطلبات','راجع طلبات العملاء وتابع حالة التنفيذ من مكان واحد.'],services:['الخدمات والباقات','أضف خدماتك وباقاتها بخطوات واضحة ومنظّمة.'],categories:['تصنيفات الخدمات','نظّم خدماتك في تصنيفات يسهل الوصول إليها.'],contact:['إعدادات التواصل','حدّث وسائل التواصل التي تظهر للعملاء.']};$('#admin-heading').textContent=headings[view][0];$('#admin-description').textContent=headings[view][1];$('#orders-tab').hidden=tab.dataset.tab!=='orders';$('#catalog-tab').hidden=tab.dataset.tab!=='catalog';$('#contact-tab').hidden=tab.dataset.tab!=='contact';if(tab.dataset.tab==='contact')run(loadContact);const category=tab.dataset.view==='categories';$('#category-editor').hidden=!category;$('#service-editor').hidden=true;$('#service-tools').hidden=category;$('#services-list').hidden=category;document.querySelectorAll('.sidebar-link[data-tab]').forEach(button=>{button.classList.toggle('active',button===tab);if(button===tab)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current')});status('')}const remove=e.target.closest('[data-remove-field]');if(remove)remove.closest('.requirement-row').remove();const order=e.target.closest('[data-order]');if(order)run(async()=>{const o=await api('/api/admin/orders/'+order.dataset.order);$('#order-detail').hidden=false;$('#order-detail').innerHTML=`<h2>${E(o.public_reference)}</h2><p>${E(o.full_name)} · <bdi dir="ltr">${E(o.phone)}</bdi></p>${o.items.map(i=>`<h3>${E(i.package_snapshot.service_name)} — ${E(i.package_snapshot.name)}</h3>${i.answers.map(a=>`<p>${E(a.field_key)}: ${E(a.value_json)}</p>`).join('')}`).join('')}<form id="update-order"><label>الحالة<select name="status"><option value="review">قيد المراجعة</option><option value="awaiting_customer">بانتظار إجراء من العميل</option><option value="ready">جاهز للتنفيذ</option><option value="processing">قيد التنفيذ</option><option value="cancelled">ملغي</option></select></label><label>رسالة ظاهرة للعميل<textarea name="note"></textarea></label><button class="button">حفظ التحديث</button></form><p class="fine">التنفيذ يتطلب دفعًا مؤكدًا. إدارة الدفع وإكمال التفعيل لم تُفعّل في هذا الإصدار.</p>`;$('#order-detail').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});$('#update-order').onsubmit=e=>{e.preventDefault();run(async()=>{await api('/api/admin/orders/'+o.id,Object.fromEntries(new FormData(e.target)));status('تم تحديث الطلب.');await refreshAfterSave()})}})});run(async()=>{const u=(await api('/api/auth/me')).user;if(u.role!=='admin')throw Error('هذه الصفحة للأدمن فقط.');$('#admin-content').hidden=false;await refresh()});

let serviceStep=0;function setServiceStep(index){serviceStep=index;document.querySelectorAll('[data-service-step]').forEach(el=>el.hidden=Number(el.dataset.serviceStep)!==index);document.querySelectorAll('[data-step-label]').forEach(el=>el.classList.toggle('active',Number(el.dataset.stepLabel)===index));$('#previous-step').hidden=index===0;$('#next-step').hidden=index===3;$('#save-service').hidden=index!==3;$('#wizard-status').textContent='الخطوة '+(index+1)+' من 4'}
$('#next-step').onclick=()=>{const active=document.querySelector('[data-service-step="'+serviceStep+'"]');for(const field of active.querySelectorAll('input,select,textarea'))if(!field.checkValidity()){status('تحقق من الحقل: '+(field.closest('label')?.childNodes[0]?.textContent?.trim()||'بيانات الخدمة'));$('#admin-notice').classList.add('error');field.reportValidity();return}if(serviceStep===0&&!$('#category-select').value){status('أضف تصنيفًا أولًا من قسم التصنيفات.');return}setServiceStep(Math.min(3,serviceStep+1))};$('#previous-step').onclick=()=>setServiceStep(Math.max(0,serviceStep-1));
const serviceForm=$('#service-form');serviceForm.noValidate=true;
const kind=serviceForm.elements.kind;function updateDuration(){const subscription=kind.value==='subscription';for(const key of ['duration_value','duration_unit']){const field=serviceForm.elements[key];field.disabled=!subscription;field.required=subscription;field.closest('label').hidden=!subscription}}kind.addEventListener('change',updateDuration);updateDuration();serviceForm.elements.pricing_mode.addEventListener('change',()=>{const price=serviceForm.elements.price;price.required=serviceForm.elements.pricing_mode.value==='fixed';price.disabled=!price.required;price.closest('label').hidden=!price.required});serviceForm.elements.pricing_mode.dispatchEvent(new Event('change'));setServiceStep(0);

function dismissAdminNotice(){const notice=$('#admin-notice');if(notice.hidden)return;notice.hidden=true;if(!matchMedia('(prefers-reduced-motion: reduce)').matches){notice.hidden=false;const animation=notice.animate([{opacity:1,transform:'translateX(-50%) translateY(0)'},{opacity:0,transform:'translateX(-50%) translateY(10px)'}],{duration:160,easing:'ease-in'});animation.finished.then(()=>notice.hidden=true).catch(()=>{})}}
$('#admin-notice').onclick=dismissAdminNotice;$('#admin-notice').addEventListener('keydown',e=>{if(['Enter',' ','Escape'].includes(e.key)){e.preventDefault();dismissAdminNotice()}});
let serviceImage=null,imageBusy=false;
function clearServiceImage(){serviceImage=null;$('#service-image').value='';$('#image-preview').hidden=true;$('#service-image-preview').removeAttribute('src');$('#image-feedback').textContent=''}
$('#remove-service-image').onclick=()=>{imageVersion++;imageBusy=false;$('#next-step').disabled=false;$('#save-service').disabled=false;clearServiceImage()};
let imageVersion=0;
$('#service-image').onchange=async()=>{const file=$('#service-image').files[0];if(!file)return;const version=++imageVersion;imageBusy=true;$('#next-step').disabled=true;$('#save-service').disabled=true;$('#image-feedback').textContent='جارٍ تجهيز الصورة…';try{const data=await OwaysImages.prepare(file);if(version!==imageVersion)return;serviceImage=data;$('#service-image-preview').src=data;$('#image-preview').hidden=false;$('#image-feedback').textContent='الصورة جاهزة. حُفظت أبعادها داخل مساحة 960 × 600 دون قطع المحتوى.'}catch(e){if(version!==imageVersion)return;$('#service-image').value='';$('#image-feedback').textContent=e.message+(serviceImage?' الصورة السابقة ما زالت محفوظة.':'');status(e.message);$('#admin-notice').classList.add('error')}finally{if(version===imageVersion){imageBusy=false;$('#next-step').disabled=false;$('#save-service').disabled=false}}};
async function loadContact(){const r=await api('/api/admin/contact');for(const key of ['whatsapp','email','phone','hours','address'])$('#contact-form').elements[key].value=r[key]||''}
$('#contact-form').onsubmit=e=>{e.preventDefault();run(async()=>{await api('/api/admin/contact',Object.fromEntries(new FormData(e.target)));status('تم حفظ معلومات التواصل.')})};

document.addEventListener('keydown',event=>{
 if(event.key!=='Enter'||event.isComposing||event.shiftKey||event.ctrlKey||event.altKey||event.metaKey)return;
 const field=event.target,form=field.closest('form');
 if(!form||!['INPUT','SELECT'].includes(field.tagName)||['file','checkbox','radio','submit','button'].includes(field.type))return;
 event.preventDefault();
 if(!field.checkValidity()){
  status('أكمل الحقل الحالي بشكل صحيح قبل الانتقال.');
  $('#admin-notice').classList.add('error');field.classList.add('field-invalid');field.focus();field.reportValidity();return;
 }
 field.classList.remove('field-invalid');
 const scope=form.id==='service-form'?document.querySelector('[data-service-step="'+serviceStep+'"]'):form;
 const fields=[...scope.querySelectorAll('input,select,textarea')].filter(el=>!el.disabled&&el.type!=='hidden'&&el.getClientRects().length>0&&!['file','checkbox','radio','submit','button'].includes(el.type));
 const next=fields[fields.indexOf(field)+1];
 if(next){next.focus();return}
 if(form.id==='service-form'&&serviceStep<3){$('#next-step').click();const step=document.querySelector('[data-service-step="'+serviceStep+'"]');step.querySelector('input:not([type=hidden]),select,textarea,button')?.focus();return}
 // The final Enter moves to the save button; a second Enter confirms the save.
 const submit=form.querySelector('button[type=submit]:not([hidden]),button:not([type])');
 if(submit&&!submit.disabled)submit.focus();
});
document.addEventListener('input',event=>{if(event.target.matches('input,select,textarea')&&event.target.checkValidity())event.target.classList.remove('field-invalid')});

document.querySelectorAll('form').forEach(form=>form.addEventListener('invalid',event=>{status('يرجى مراجعة الحقل المحدد وإكمال البيانات المطلوبة.');$('#admin-notice').classList.add('error')},true));

function showSuccess(message){$('#admin-notice').hidden=true;$('#success-message').textContent=message;const dialog=$('#success-card');if(!dialog.open)dialog.showModal();$('#confirm-success').focus()}
$('#close-success').onclick=()=>$('#success-card').close();$('#confirm-success').onclick=()=>$('#success-card').close();
async function refreshAfterSave(){try{await refresh()}catch{status('حُفظت البيانات، لكن تعذر تحديث القائمة. حدّثها لاحقًا؛ لا تعِد الحفظ.');}}
function validateService(){for(const field of serviceForm.querySelectorAll('input,select,textarea')){if(field.disabled||field.type==='hidden')continue;if(!field.checkValidity()){const step=field.closest('[data-service-step]');if(step)setServiceStep(Number(step.dataset.serviceStep));status('يرجى مراجعة الحقل المحدد وإكمال البيانات المطلوبة.');$('#admin-notice').classList.add('error');field.focus();field.classList.remove('field-invalid');void field.offsetWidth;field.classList.add('field-invalid');field.reportValidity();return false}}return true}
document.addEventListener('input',event=>event.target.classList?.remove('field-invalid'));

const sidebarPaths=['M4 4h16v16H4z M8 8h8 M8 12h8 M8 16h5','M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z','M3 3h8l10 10-8 8L3 11z M7 7h.01','M4 4h16v16H4z M4 6l8 7 8-7','M14 3h7v7 M21 3l-11 11 M10 3H3v18h18v-7'];
document.querySelectorAll('.admin-sidebar .sidebar-link').forEach((el,i)=>{const text=el.querySelector('span');el.replaceChildren();const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('fill','none');svg.setAttribute('stroke','currentColor');svg.setAttribute('stroke-width','1.7');svg.setAttribute('stroke-linecap','round');svg.setAttribute('stroke-linejoin','round');svg.setAttribute('aria-hidden','true');const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',sidebarPaths[i]);svg.append(path);el.append(svg,text);if(i===0)el.setAttribute('aria-current','page')});

let adminServices=[];
const durationLabels={day:'يوم',week:'أسبوع',month:'شهر',year:'سنة'};
function renderAdminServices(){
 const query=$('#service-search').value.trim().toLocaleLowerCase(),category=$('#service-category-filter').value;
 const services=adminServices.filter(s=>(!category||String(s.category_id)===category)&&(!query||[s.name,s.category_name].some(v=>String(v||'').toLocaleLowerCase().includes(query))));
 $('#services-summary').textContent='عرض '+services.length+' من '+adminServices.length+' خدمة';
 $('#services').innerHTML=services.length?services.map(s=>`<article class="admin-service-card"><div class="service-card-heading"><div><small>${E(s.category_name)}</small><h3>${E(s.name)}</h3></div><span class="admin-badge" data-state="${E(s.status)}">${E(adminState(s.status))}</span></div><p class="service-card-description">${E(s.description||'')}</p><div class="service-kind">${s.kind==='subscription'?'اشتراك رقمي':'خدمة لمرة واحدة'} · ${s.packages.length} باقة</div><div class="service-package-list">${s.packages.map(p=>`<div class="service-package-row"><div><strong>${E(p.name)}</strong><small>${p.duration_value?E(p.duration_value)+' '+E(durationLabels[p.duration_unit]||''): 'تنفيذ لمرة واحدة'}</small></div><div class="package-price">${p.pricing_mode==='quote'?'حسب عرض السعر':E(p.price)+' <bdi>'+E(p.currency)+'</bdi>'}<small>${E(adminState(p.status))}</small></div></div>`).join('')||'<p class="fine">لا توجد باقات مضافة.</p>'}</div><a class="button outline" href="/account?service=${encodeURIComponent(s.slug)}">معاينة طلب الخدمة ←</a></article>`).join(''):'<div class="admin-empty"><h3>لا توجد خدمات مطابقة</h3><p>أضف خدمة جديدة أو عدّل البحث والتصنيف.</p></div>';
}
$('#service-search').addEventListener('input',renderAdminServices);$('#service-category-filter').addEventListener('change',renderAdminServices);
$('#service-editor').hidden=true;
$('#open-service-editor').onclick=()=>{$('#service-editor').hidden=!$('#service-editor').hidden;if(!$('#service-editor').hidden){$('#service-editor').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});serviceForm.elements.name.focus({preventScroll:true})}};
